'use strict';
// سرور مدرسه قازی‌زاده — بدون نیاز به نصب بسته؛ فقط Node.js 18 یا بالاتر
const http = require('http'), fs = require('fs'), path = require('path'), crypto = require('crypto');
const PORT = +process.env.PORT || 3000;
const DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
const FILE = path.join(DIR, 'data.json');
const INDEX = Buffer.from('', 'base64'); // صفحه سایت داخل همین فایل است
const KEY = process.env.ANTHROPIC_API_KEY || '';
const AI_URL = process.env.ANTHROPIC_URL || 'https://api.anthropic.com/v1/messages';
const M_FAST = process.env.MODEL_FAST || 'claude-haiku-5-5', M_MAIN = process.env.MODEL || 'claude-sonnet-5-5';

fs.mkdirSync(DIR, { recursive: true });
const hash = (s, salt) => crypto.scryptSync(String(s), salt, 32).toString('hex');
let db = null;
try { db = JSON.parse(fs.readFileSync(FILE, 'utf8')); } catch (e) {}
if (!db) {
  const salt = crypto.randomBytes(16).toString('hex');
  db = { secret: crypto.randomBytes(32).toString('hex'), admin: { salt, hash: hash(process.env.ADMIN_PASSWORD || 'koppok', salt) }, users: [], news: [], notes: [], cache: {} };
  save();
}
function save() { const t = FILE + '.tmp'; fs.writeFileSync(t, JSON.stringify(db)); fs.renameSync(t, FILE); }

const b64 = b => Buffer.from(b).toString('base64url');
const mac = d => crypto.createHmac('sha256', db.secret).update(d).digest('base64url');
const sign = p => { const d = b64(JSON.stringify(p)); return d + '.' + mac(d); };
function verify(t) {
  if (!t) return null;
  const [d, s] = t.split('.'); if (!s) return null;
  const e = mac(d); if (e.length !== s.length || !crypto.timingSafeEqual(Buffer.from(e), Buffer.from(s))) return null;
  try {
    const p = JSON.parse(Buffer.from(d, 'base64url')); if (p.e < Date.now()) return null;
    if (p.r !== 'admin') { const u = db.users.find(x => x.id === p.i); if (!u || !u.ok) return null; }
    return p;
  } catch (e) { return null; }
}
const hits = new Map();
const limited = (k, max, ms) => { const n = Date.now(), a = (hits.get(k) || []).filter(t => n - t < ms); a.push(n); hits.set(k, a); return a.length > max; };
setInterval(() => hits.clear(), 600000).unref();

const send = (res, c, o) => { res.writeHead(c, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }); res.end(JSON.stringify(o)); };
const err = (c, m) => Object.assign(new Error(m), { code: c });
const norm = s => String(s || '').trim().replace(/\s+/g, ' ').slice(0, 60);
const cut = (s, n) => String(s || '').slice(0, n);
const rid = () => crypto.randomBytes(6).toString('hex');
const day = () => new Date().toLocaleDateString('fa-IR');
function readBody(req) {
  return new Promise((ok, no) => {
    let b = ''; req.on('data', c => { b += c; if (b.length > 200000) { no(err(413, 'حجم درخواست زیاد است')); req.destroy(); } });
    req.on('end', () => { try { ok(b ? JSON.parse(b) : {}); } catch (e) { no(err(400, 'درخواست نامعتبر')); } });
  });
}
async function askAI(model, max, system, messages) {
  if (!KEY) throw err(503, 'کلید هوش مصنوعی روی سرور تنظیم نشده است');
  const r = await fetch(AI_URL, { method: 'POST', headers: { 'content-type': 'application/json', 'x-api-key': KEY, 'anthropic-version': '2023-06-01' }, body: JSON.stringify({ model, max_tokens: max, system, messages }) });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) throw err(502, 'خطا از سرویس هوش مصنوعی');
  return (d.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
}
const PERSONA = 'تو «مصطفی» هستی، دستیار هوشمند درسی مدرسه مشارکتی مرحوم مهندس حاج مصطفی قازی‌زاده. مهربان، دقیق و ساده به فارسی جواب بده و مثل معلم دبستان توضیح بده. اگر مطمئن نیستی، صادقانه بگو و چیزی را اختراع نکن.';
const NOTE_SYS = 'تو معلم باتجربه دبستان در ایران هستی و جزوه درسی منظم و دقیق به فارسی ساده می‌نویسی. فقط از ## و - و **bold** استفاده کن، بدون جدول.';

async function api(req, res, u) {
  const ip = req.socket.remoteAddress, m = req.method, p = u.pathname.slice(4);
  const me = verify((req.headers.authorization || '').replace('Bearer ', ''));
  if (m === 'GET' && p === '/state') {
    const o = { me: me ? { role: me.r, name: me.n } : null, news: db.news.slice().reverse() };
    if (me) o.notes = db.notes.slice().reverse();
    if (me && me.r === 'admin') {
      const L = r => db.users.filter(x => x.role === r).map(x => ({ id: x.id, n: x.name, ok: x.ok }));
      o.students = L('student'); o.teachers = L('teacher');
    }
    return send(res, 200, o);
  }
  const b = (m === 'POST') ? await readBody(req) : {};
  if (m === 'POST' && p === '/login') {
    if (limited('l' + ip, 10, 60000)) throw err(429, 'تلاش زیاد؛ کمی بعد دوباره امتحان کنید');
    const n = norm(b.name); if (!n) throw err(400, 'نام را وارد کنید');
    const h = hash(b.password || '', db.admin.salt);
    if (!crypto.timingSafeEqual(Buffer.from(h), Buffer.from(db.admin.hash))) throw err(401, 'رمز اشتباه است');
    return send(res, 200, { token: sign({ i: 'admin', r: 'admin', n, e: Date.now() + 864e5 }) });
  }
  if (m === 'POST' && p === '/enter') {
    if (limited('e' + ip, 20, 60000)) throw err(429, 'تلاش زیاد؛ کمی بعد دوباره امتحان کنید');
    const role = b.role === 'teacher' ? 'teacher' : 'student', n = norm(b.name), c = cut(b.code, 40);
    if (!n || !c) throw err(400, 'نام و کد را وارد کنید');
    let u = db.users.find(x => x.role === role && x.name.toLowerCase() === n.toLowerCase());
    if (!u) {
      const salt = crypto.randomBytes(16).toString('hex');
      db.users.push({ id: rid(), role, name: n, salt, hash: hash(c, salt), ok: false, at: day() }); save();
      return send(res, 200, { status: 'pending', created: true });
    }
    if (hash(c, u.salt) !== u.hash) throw err(403, 'کد اشتباه است');
    if (!u.ok) return send(res, 200, { status: 'pending' });
    return send(res, 200, { status: 'ok', token: sign({ i: u.id, r: role, n: u.name, e: Date.now() + 7 * 864e5 }) });
  }
  if (!me) throw err(401, 'ابتدا وارد شوید');
  const adminOnly = () => { if (me.r !== 'admin') throw err(403, 'فقط مدیر'); };
  if (m === 'POST' && p === '/news') { adminOnly(); const t = cut(b.title, 150).trim(); if (!t) throw err(400, 'عنوان لازم است'); db.news.push({ id: rid(), t, b: cut(b.body, 5000), d: day() }); save(); return send(res, 200, { ok: 1 }); }
  if (m === 'DELETE' && p.startsWith('/news/')) { adminOnly(); db.news = db.news.filter(x => x.id !== p.slice(6)); save(); return send(res, 200, { ok: 1 }); }
  if (m === 'POST' && p === '/notes') { if (me.r !== 'teacher') throw err(403, 'فقط معلم'); const t = cut(b.title, 150).trim(); if (!t) throw err(400, 'عنوان لازم است'); db.notes.push({ id: rid(), t, b: cut(b.body, 20000), a: me.n, uid: me.i, d: day() }); save(); return send(res, 200, { ok: 1 }); }
  if (m === 'DELETE' && p.startsWith('/notes/')) { const id = p.slice(7), n = db.notes.find(x => x.id === id); if (n && (me.r === 'admin' || n.uid === me.i)) { db.notes = db.notes.filter(x => x.id !== id); save(); } return send(res, 200, { ok: 1 }); }
  if (m === 'POST' && p === '/approve') { adminOnly(); const u = db.users.find(x => x.id === b.id); if (u) { u.ok = true; save(); } return send(res, 200, { ok: 1 }); }
  if (m === 'DELETE' && p.startsWith('/users/')) { adminOnly(); db.users = db.users.filter(x => x.id !== p.slice(7)); save(); return send(res, 200, { ok: 1 }); }
  if (m === 'POST' && p === '/admin/password') {
    adminOnly();
    if (hash(b.old || '', db.admin.salt) !== db.admin.hash) throw err(403, 'رمز فعلی اشتباه است');
    if (String(b.new || '').length < 4) throw err(400, 'رمز جدید باید حداقل ۴ حرف باشد');
    const salt = crypto.randomBytes(16).toString('hex'); db.admin = { salt, hash: hash(b.new, salt) }; save(); return send(res, 200, { ok: 1 });
  }
  if (m === 'POST' && p === '/chat') {
    if (limited('c' + me.i, 40, 600000)) throw err(429, 'تعداد پیام‌ها زیاد است؛ کمی صبر کنید');
    if (b.mode === 'gen') {
      const prompt = cut(b.prompt, 3000); if (!prompt) throw err(400, 'درخواست خالی است');
      const key = /^[1-6]\|[^|]{1,40}\|\d{1,2}$/.test(b.cacheKey || '') ? b.cacheKey : null;
      if (key && !b.force && db.cache[key]) return send(res, 200, { text: db.cache[key], cached: true });
      const text = await askAI(M_MAIN, 2000, NOTE_SYS, [{ role: 'user', content: prompt }]);
      if (key && text) { db.cache[key] = text; save(); }
      return send(res, 200, { text });
    }
    const raw = (Array.isArray(b.messages) ? b.messages : []).slice(-12).filter(x => x && (x.role === 'user' || x.role === 'assistant')).map(x => ({ role: x.role, content: cut(x.content, 3000) }));
    const msgs = []; for (const x of raw) { const l = msgs[msgs.length - 1]; if (l && l.role === x.role) l.content += '\n' + x.content; else msgs.push(x); }
    while (msgs.length && msgs[0].role !== 'user') msgs.shift();
    if (!msgs.length) throw err(400, 'پیام خالی است');
    return send(res, 200, { text: await askAI(M_FAST, 1000, PERSONA, msgs) });
  }
  throw err(404, 'یافت نشد');
}
const _unused = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.css': 'text/css', '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml', '.ico': 'image/x-icon', '.woff2': 'font/woff2' };
http.createServer(async (req, res) => {
  res.setHeader('X-Content-Type-Options', 'nosniff'); res.setHeader('Referrer-Policy', 'same-origin');
  try {
    const u = new URL(req.url, 'http://x');
    if (u.pathname.startsWith('/api/')) return await api(req, res, u);
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' });
    return res.end(INDEX);
  } catch (e) {
    if (!res.headersSent) send(res, typeof e.code === 'number' ? e.code : 500, { error: typeof e.code === 'number' ? e.message : 'خطای سرور' });
    if (typeof e.code !== 'number') console.error(e);
  }
}).listen(PORT, () => console.log('School server running on http://localhost:' + PORT));
